/// Given a non-empty slice `a` of 32-bit integers and a positive prefix length `n`
/// (with `n <= a.len()`), returns an index `r` in `[0, n)` such that
/// `a[r]` is maximal among `a[0..n]`. Ties are broken by returning the first
/// occurrence of the maximum.
fn findMax(a: &[i32], n: usize) -> usize {
    // Precondition checks (can be omitted if guaranteed by the caller)
    assert!(n > 0, "prefix length must be positive");
    assert!(n <= a.len(), "prefix length must not exceed the array length");

    // Initialize `max_idx` to the first position in the prefix
    let mut max_idx = 0;

    // Scan the prefix [1..n), updating `max_idx` whenever we find a strictly larger element.
    for i in 1..n {
        if a[i] > a[max_idx] {
            max_idx = i;
        }
    }

    max_idx
}

